abstract class Vehicle { protected String number; Vehicle(String n){number=n;} abstract double hourlyRate(); } class TwoWheeler extends Vehicle {TwoWheeler(String n){super(n);} double hourlyRate(){return 15;}} class Car extends Vehicle {Car(String n){super(n);} double hourlyRate(){return 30;}} class ElectricCar extends Car {ElectricCar(String n){super(n);} double chargingRate(){return 10;}} public class Main {public static void main(String[]a){Vehicle v=new TwoWheeler("TN01"),c=new Car("TN02");System.out.println(v.number+" Rs."+v.hourlyRate());System.out.println(c.number+" Rs."+c.hourlyRate());System.out.println("EV charging add-on Rs."+new ElectricCar("EV01").chargingRate());}}
